DROP TABLE IF EXISTS inbox_messages;

DROP TABLE IF EXISTS approval_rules;

DROP VIEW IF EXISTS inbox_stats_by_user;

CREATE TABLE IF NOT EXISTS inbox_messages (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  source_type text NOT NULL CHECK (source_type IN ( 'whatsapp', 'telegram', 'gmail', 'github', 'discord', 'slack', 'webhook', 'manual', 'other' )),
  source_id text,
  message text NOT NULL,
  metadata text DEFAULT '{}',
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ( 'pending', 'processing', 'completed', 'failed', 'needs_approval' )),
  risk_level text CHECK (risk_level IN ('low', 'medium', 'high')),
  auto_executed integer DEFAULT 0,
  approval_needed integer DEFAULT 0,
  approval_status text CHECK (approval_status IS NULL OR approval_status IN ( 'pending', 'approved', 'denied' )),
  approved_by text,
  approved_at timestamptz,
  result text,
  error text,
  received_at timestamptz NOT NULL DEFAULT now(),
  processed_at timestamptz,
  completed_at timestamptz
);

CREATE INDEX IF NOT EXISTS idx_inbox_status ON inbox_messages (status);

CREATE INDEX IF NOT EXISTS idx_inbox_user_status ON inbox_messages (user_id, status);

CREATE INDEX IF NOT EXISTS idx_inbox_approval ON inbox_messages (approval_needed, approval_status);

CREATE INDEX IF NOT EXISTS idx_inbox_received ON inbox_messages (received_at DESC);

CREATE INDEX IF NOT EXISTS idx_inbox_risk ON inbox_messages (risk_level);

CREATE TABLE IF NOT EXISTS approval_rules (
  id text PRIMARY KEY,
  user_id text NOT NULL,
  source_type text,
  action_pattern text,
  risk_level text CHECK (risk_level IS NULL OR risk_level IN ('low', 'medium', 'high')),
  auto_approve integer DEFAULT 0,
  auto_deny integer DEFAULT 0,
  priority bigint DEFAULT 5,
  name text NOT NULL,
  description text,
  enabled integer DEFAULT 1,
  times_applied bigint DEFAULT 0,
  confidence_score double precision DEFAULT 0.0 CHECK (confidence_score >= 0.0 AND confidence_score <= 1.0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (NOT (auto_approve = 1 AND auto_deny = 1)),
  CHECK (priority >= 1 AND priority <= 10)
);

CREATE INDEX IF NOT EXISTS idx_rules_user ON approval_rules (user_id);

CREATE INDEX IF NOT EXISTS idx_rules_enabled ON approval_rules (enabled, priority DESC);

CREATE INDEX IF NOT EXISTS idx_rules_source ON approval_rules (source_type);
